        # 2 hold three items under name
        ("Mr Ashcott", "Lan, would you like me to hold these three items under your name until Friday?", "Chị Lan, chị có muốn tôi giữ ba món này dưới tên chị đến thứ Sáu không?"),
        ("Ms Lan", "Yes please, could you write my name on each one so nothing gets mixed up?", "Có chứ, anh ghi tên tôi lên từng món để khỏi lẫn được không?"),
        ("Mr Ashcott", "Certainly, I'll tag them right now and keep them behind the counter.", "Được chứ, tôi gắn thẻ ngay và để sau quầy cho chị."),
        # 3 rain check
        ("Ms Lan", "Could I get a rain check on that sale price, Ashcott? The last one just sold.", "Anh Ashcott, cho tôi xin phiếu giữ giá khuyến mãi được không? Cái cuối cùng vừa bán mất rồi."),
        ("Mr Ashcott", "Of course, I'll write you a rain check good for two weeks.", "Được chứ, tôi viết cho chị phiếu giữ giá có hiệu lực hai tuần."),
        ("Ms Lan", "Thank you, I'll come back once the new stock arrives.", "Cảm ơn anh, khi nào hàng mới về tôi sẽ quay lại."),
        # 4 emailed receipt
        ("Mr Ashcott", "Lan, would you like this receipt emailed instead of printed?", "Chị Lan, chị muốn tôi gửi hóa đơn qua email thay vì in ra không?"),
        ("Ms Lan", "Yes please, could you send it to the address on my loyalty account?", "Có chứ, anh gửi tới địa chỉ trong tài khoản thành viên của tôi được không?"),
        ("Mr Ashcott", "Sure, it should arrive in your inbox within a minute.", "Được chứ, chắc chỉ một phút nữa là vào hộp thư của chị."),
        # 5 specific staff member
        ("Ms Lan", "Could you ask Sarah to help me again, Ashcott? She helped me choose curtains last time.", "Anh Ashcott, anh nhờ giúp chị Sarah ra hỗ trợ tôi lần nữa được không? Lần trước chị ấy giúp tôi chọn rèm."),
        ("Mr Ashcott", "Of course, let me page her, she should be free in a moment.", "Được chứ, để tôi gọi chị ấy, chắc chị ấy sẽ rảnh ngay thôi."),
        ("Ms Lan", "Thank you, she really understood what I was looking for.", "Cảm ơn anh, chị ấy hiểu đúng ý tôi muốn tìm lắm."),
        # 6 private fitting room
        ("Mr Ashcott", "Lan, would you like me to unlock the private fitting room for you?", "Chị Lan, chị có muốn tôi mở phòng thử đồ riêng cho chị không?"),
        ("Ms Lan", "Yes please, that would be more comfortable with all these dresses.", "Có chứ, vậy sẽ thoải mái hơn với bấy nhiêu bộ váy này."),
        ("Mr Ashcott", "Here's the key, take as long as you need in there.", "Đây là chìa khóa, chị cứ thử thoải mái trong đó."),
        # 7 leave with neighbor
        ("Ms Lan", "Could you ask the delivery driver to leave my package with my neighbor, Ashcott? I'll be at work.", "Anh Ashcott, anh nhờ tài xế để gói hàng của tôi cho hàng xóm được không? Tôi sẽ đi làm."),
        ("Mr Ashcott", "Of course, I'll note that instruction on your delivery slip.", "Được chứ, tôi ghi chú điều đó vào phiếu giao hàng của chị."),
        ("Ms Lan", "Thank you, my neighbor is usually home in the afternoons.", "Cảm ơn anh, hàng xóm tôi thường có nhà vào buổi chiều."),
